#define main historical_main
#include "../matrixT-cuda/main.cu"
#undef main
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
std::vector<float> oracle(std::vector<float>&in,int N,int kind){std::vector<float>out(N*N);for(int y=0;y<N;y++)for(int x=0;x<N;x++){if(kind<=1)out[y*N+x]=in[y*N+x];else if(kind==2){int ox=(y/16)*16+x%16,oy=(x/16)*16+y%16;out[oy*N+ox]=in[y*N+x];}else if(kind==3){int sx=(x/16)*16+y%16,sy=(y/16)*16+x%16;out[y*N+x]=in[sy*N+sx];}else out[x*N+y]=in[y*N+x];}return out;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int N=128;std::vector<float>input(N*N);for(int i=0;i<N*N;i++)input[i]=float(i);float*dx,*out[9];CK(cudaMalloc(&dx,N*N*4));CK(cudaMemcpy(dx,input.data(),N*N*4,cudaMemcpyHostToDevice));void(*kernels[9])(float*,const float*,int,int)={copy,copySharedMem,transposeCoarseGrained,transposeFineGrained,transposeNaive,transposeCoalesced,transposeNoBankConflicts,transposeSwizzle,transposeDiagonal};std::vector<std::vector<float>>gold;for(int kind=0;kind<9;kind++){CK(cudaMalloc(&out[kind],N*N*4));CK(cudaMemset(out[kind],0xff,N*N*4));gold.push_back(oracle(input,N,kind));kernels[kind]<<<dim3(8,8),dim3(16,16)>>>(out[kind],dx,N,N);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){bool ok=true;double seconds=0;std::vector<float>output;std::vector<double>times;for(int kind=0;kind<9;kind++){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)kernels[kind]<<<dim3(8,8),dim3(16,16)>>>(out[kind],dx,N,N);CK(cudaDeviceSynchronize());double one=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;seconds+=one;times.push_back(one);std::vector<float>got(N*N);CK(cudaMemcpy(got.data(),out[kind],N*N*4,cudaMemcpyDeviceToHost));ok&=got==gold[kind];output.insert(output.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"matrixT_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_all9_copy_partial_and_complete_transpose_kernels\",\"jit_excluded\":true,\"internal_repeats\":%d,\"case_times_seconds\":[",trial,seconds,ok?"true":"false",output.size(),repeat);for(int i=0;i<9;i++)printf("%s%.12g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",file,output.size());}for(int i=0;i<9;i++)CK(cudaFree(out[i]));CK(cudaFree(dx));puts(allok?"PASS":"FAIL");return allok?0:1;}
